package com.termux.app.workspace;
import android.app.Application;import android.view.View;import com.termux.shared.terminal.io.extrakeys.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class ExtraKeysEnterRowTest {
 @Test public void enterPrecedesPageBlockAndRowsRemain()throws Exception{ExtraKeysInfo info=new ExtraKeysInfo("[['ESC','PGUP'],['TAB','PGDN']]","default",ExtraKeysConstants.CONTROL_CHARS_ALIASES);ExtraKeyButton[][] rows=info.getMatrix();assertEquals(2,rows.length);assertEquals("ENTER",rows[0][1].getKey());assertEquals("",rows[1][1].getKey());assertEquals("ESC",rows[0][0].getKey());assertEquals("TAB",rows[1][0].getKey());assertEquals("PGUP",rows[0][2].getKey());assertEquals("PGDN",rows[1][2].getKey());assertEquals(Integer.valueOf(android.view.KeyEvent.KEYCODE_ENTER),ExtraKeysConstants.PRIMARY_KEY_CODES_FOR_STRINGS.get(rows[0][1].getKey()));}
 @Test public void modifierUsesYellowAndRestoresNormalIncludingReload()throws Exception{ExtraKeysView keys=new ExtraKeysView(RuntimeEnvironment.application,null);WorkspaceExtraKeysStyle.apply(keys);ExtraKeysInfo info=new ExtraKeysInfo("[['CTRL']]","default",ExtraKeysConstants.CONTROL_CHARS_ALIASES);keys.reload(info);android.widget.Button ctrl=(android.widget.Button)keys.getChildAt(0);SpecialButtonState state=keys.getSpecialButtons().get(SpecialButton.CTRL);state.setIsActive(true);assertEquals(0xffffd54f,ctrl.getCurrentTextColor());state.setIsLocked(true);keys.reload(info);ctrl=(android.widget.Button)keys.getChildAt(0);assertEquals(0xffffd54f,ctrl.getCurrentTextColor());state.setIsLocked(false);state.setIsActive(false);assertEquals(WorkspaceDialogs.TEXT,ctrl.getCurrentTextColor());}
 @Test public void existingEnterAndLayoutsWithoutPageUpAreNotDuplicated()throws Exception{for(String json:new String[]{"[['ENTER','PGUP']]","[['ESC','TAB']]"})assertEquals(1,new ExtraKeysInfo(json,"default",ExtraKeysConstants.CONTROL_CHARS_ALIASES).getMatrix().length);}
}
